import { isPlatformBrowser } from '@angular/common';
import { Component, OnInit, OnDestroy, HostListener, ViewEncapsulation, Inject, PLATFORM_ID, AfterViewChecked} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Subject, combineLatest, Observable } from 'rxjs';
import { takeUntil, debounceTime, distinctUntilChanged, switchMap, map } from 'rxjs/operators';
import { trigger, transition, style, animate } from '@angular/animations';
import { UsuarioStateService} from './../../../../services/usuario-state.service';
import { UsuarioService } from './../../../../services/usuario.service';
import { RolesModalComponent } from './components/roles-modal/roles-modal.component';
import { CatalogoService } from '../../../../services/catalogo.service';
import { UsuarioFiltersComponent } from './components/usuario-filters/usuario-filters.component';
import { UsuariosListComponent } from './components/usuarios-list/usuarios-list.component';
import { UsuarioFormComponent } from './components/usuario-form/usuario-form.component';
import { MenuComponent } from '../../../../layouts/menu/menu.component';
import { HeaderComponent } from '../../../../layouts/header/header.component';
import { NotificationService } from '../../../../core/services/notification/notification.service';  // ✅ Ruta corregida a shared/services
import { FooterComponent } from '../../../../layouts/footer/footer.component';
import { HelpSupportComponent } from '../../../dashboard/components/help-support/help-support.component';
import { usuarioValidators } from './validators/usuario.validators';
import { Usuario } from './models/usuario.model';
import { ThemeService, ThemeType } from '../../../../shared/features/home/services/theme.service';
import { LoadingService } from '../../../../core/services/loading.service';
import { ModuleLoaderService } from '../../../../core/services/module-loader.service';

@Component({
  selector: 'app-usuarios',
  standalone: true,
  encapsulation: ViewEncapsulation.None,
  imports: [
    CommonModule,
    FormsModule,
    MenuComponent,
    RolesModalComponent,
    HeaderComponent,
    FooterComponent,
    HelpSupportComponent,
    UsuarioFiltersComponent,
    UsuariosListComponent,
    UsuarioFormComponent
  ],
  templateUrl: './usuarios.component.html',
  styleUrls: ['./usuarios.component.scss'],
  animations: [
    trigger('fadeIn', [
      transition(':enter', [style({ opacity: 0 }), animate('200ms', style({ opacity: 1 }))]),
      transition(':leave', [animate('150ms', style({ opacity: 0 }))])
    ]),
    trigger('slideDown', [
      transition(':enter', [style({ opacity: 0, transform: 'translateY(-20px)' }), animate('300ms', style({ opacity: 1, transform: 'translateY(0)' }))]),
      transition(':leave', [animate('200ms', style({ opacity: 0, transform: 'translateY(-20px)' }))])
    ])
  ]
})
export class UsuariosComponent implements OnInit, OnDestroy, AfterViewChecked {
     private moduleName = 'Administración de Usuarios';
  private dataLoaded = false;
  private isMarkedReady = false;
  private viewCheckedCount = 0;

  // Layout variables
  isSidebarCollapsed = false;
  showHelpSupport = false;
  isMinimized = false;
  showMinimizeNotification = false;
  minimizing = false;
  isSearchOpen = false;
  isNotificationsOpen = false;
  isUserMenuOpen = false;
  searchQuery = '';
  searchResults: any[] = [];
currentTheme: ThemeType = 'light';
  // Usuario variables
  usuarios$!: Observable<Usuario[]>;
  loading$!: Observable<boolean>;
  totalItems$!: Observable<number>;
  currentPage$!: Observable<number>;
  usuariosActivos$!: Observable<number>;

  showUsuarioModal = false;
  showPasswordModal = false;
  showDeleteModal = false;
  showRolesModal = false;
  showReportesModal = false;
  showValidacionModal = false;
  modalTitle = 'Nuevo Usuario';
  isEditing = false;
  currentUsuario: Usuario | null = null;
  passwordData: any = { currentPassword: '', newPassword: '', confirmPassword: '', contrasena: '' };

  // Password visibility
  showPassword = false;
  showCurrentPassword = false;
  showNewPassword = false;
  showConfirmPassword = false;

  passwordError = '';
  passwordReqs = { minLength: false, hasUppercase: false, hasLowercase: false, hasNumber: false, hasSpecial: false, valid: false };

  // Notifications
  notifications = [
  ];

  user = { name: 'Admin SIGPAZ', email: 'admin@sigpaz.com', avatar: 'A', role: 'Administrador' };
  isBrowser: boolean;
  private destroy$ = new Subject<void>();
  private filterSubject = new Subject<any>();

  constructor(
    private usuarioState: UsuarioStateService,
    private usuarioService: UsuarioService,
    private catalogoService: CatalogoService,
    private themeService: ThemeService,
         private moduleLoader: ModuleLoaderService,
        private loadingService: LoadingService,
    private notificationService: NotificationService,
    @Inject(PLATFORM_ID) private platformId: Object
  ) {this.isBrowser = isPlatformBrowser(this.platformId);}

  ngOnInit(): void {
    this.usuarios$ = this.usuarioState.selectUsuarios();
    this.loading$ = this.usuarioState.selectLoading();
    this.totalItems$ = this.usuarioState.selectTotalItems();
    this.currentPage$ = this.usuarioState.selectCurrentPage();
    this.usuariosActivos$ = this.usuarios$.pipe(map(usuarios => usuarios.filter(u => u.activo).length));

    this.setupFilterSubscription();
    this.loadUsuarios();
    this.setupThemeSubscription();
       this.moduleLoader.registerComponentInstance(this.moduleName, this);
    this.loadModuleData();
  }

  ngAfterViewChecked() {
    // Después de cada verificación de vista, si ya está marcado, no hacer nada
    if (this.isMarkedReady) return;

    this.viewCheckedCount++;

    // Esperar a que Angular termine de renderizar completamente
    if (this.dataLoaded && this.viewCheckedCount >= 2) {
      console.log(`✅ Vista completamente estable (afterViewChecked x${this.viewCheckedCount})`);
      this.checkAndMarkReady();
    }
  }

  private async loadModuleData(): Promise<void> {
    try {
      console.log(`📡 Cargando datos para: ${this.moduleName}`);

      // Simular carga de datos
      await Promise.all([
        this.fetchData('/api/personal'),
        this.fetchData('/api/tipos-documento'),
        this.fetchData('/api/generos')
      ]);

      this.dataLoaded = true;
      console.log(`✅ Datos cargados para: ${this.moduleName}`);

      // Forzar detección de cambios
      setTimeout(() => {
        this.checkAndMarkReady();
      }, 100);

    } catch (error) {
      console.error(`❌ Error cargando datos:`, error);
      this.markModuleAsReady(); // Ocultar loading aunque haya error
    }
  }


  private checkAndMarkReady(): void {
  if (this.isMarkedReady) return;

  const hasContent = document.querySelector('.users-container, .main-content, app-usuarios');
  const hasData = document.querySelector('.stats-container, app-usuarios-list, .data-table');

  console.log(`🔍 [Usuarios] Verificando contenido: hasContent=${!!hasContent}, hasData=${!!hasData}`);

  if (this.dataLoaded && hasContent && hasData) {
    this.markModuleAsReady();
  } else if (this.dataLoaded) {
    setTimeout(() => this.checkAndMarkReady(), 200);
  }
}

  private markModuleAsReady(): void {
    if (this.isMarkedReady) return;
    this.isMarkedReady = true;
    console.log(`🏁 Marcando módulo como listo: ${this.moduleName}`);
    this.moduleLoader.markModuleRendered(this.moduleName);
  }

  private fetchData(url: string): Promise<any> {
    return new Promise(resolve => setTimeout(resolve, 500));
  }

   private setupThemeSubscription(): void {
        this.themeService.theme$
          .pipe(takeUntil(this.destroy$))
          .subscribe(theme => {
            this.currentTheme = theme;
          });
      }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
      this.moduleLoader.markModuleRendered(this.moduleName);
  }

  private setupFilterSubscription(): void {
    this.filterSubject.pipe(debounceTime(300), distinctUntilChanged(), takeUntil(this.destroy$))
      .subscribe(() => { this.usuarioState.setCurrentPage(1); this.loadUsuarios(); });
  }

  private loadUsuarios(): void {
    this.usuarioState.setLoading(true);
    combineLatest([this.usuarioState.selectCurrentPage(), this.usuarioState.selectFilters()]).pipe(
      takeUntil(this.destroy$),
      switchMap(([page, filters]) => this.usuarioService.listar({ ...filters, page, per_page: 10 }))
    ).subscribe({
      next: (response) => {
        this.usuarioState.setUsuarios(response.data, response.meta.total);
        this.notificationService?.showSuccess('Usuarios cargados correctamente', 2000);
      },
      error: (error) => {
        this.usuarioState.setError(error.message || 'Error al cargar usuarios');
        this.notificationService?.showError('Error al cargar usuarios');
      }
    });
  }

  // ========== LAYOUT METHODS ==========


  openSearchModal(): void { this.isSearchOpen = true; }
  closeSearchModal(): void { this.isSearchOpen = false; this.searchQuery = ''; this.searchResults = []; }
  performSearch(): void { if (this.searchQuery.trim()) this.searchResults = []; }
  clearSearch(): void { this.searchQuery = ''; this.searchResults = []; }

  markAllAsRead(): void { this.notifications.forEach(n =>true); }


 onToggleHelpSupport(): void {
    this.showHelpSupport = !this.showHelpSupport;
    if (!this.showHelpSupport) {
      if (this.isBrowser) {
        document.body.classList.remove('minimized-mode');
      }
    }
  }

  minimizeToBubble(): void { this.isMinimized = true; this.showMinimizeNotification = true; setTimeout(() => this.showMinimizeNotification = false, 3000); }
  restoreFromBubble(): void { this.isMinimized = false; }
  closeBubble(event: MouseEvent): void { event.stopPropagation(); this.showHelpSupport = false; this.isMinimized = false; }
  handleOverlayClick(event: MouseEvent): void { if ((event.target as HTMLElement).classList.contains('modal-overlay-sigpaz') && this.showHelpSupport && !this.isMinimized) this.minimizeToBubble(); }

  @HostListener('document:click', ['$event'])
  onClickOutside(event: MouseEvent): void {
    const target = event.target as HTMLElement;
    if (!target.closest('.notification-wrapper') && !target.closest('.notifications-dropdown')) this.isNotificationsOpen = false;
    if (!target.closest('.user-menu-wrapper') && !target.closest('.user-dropdown')) this.isUserMenuOpen = false;
    if (!target.closest('.search-modal-content') && !target.closest('.search-button')) this.isSearchOpen = false;
  }

  // ========== USUARIO METHODS ==========
  onPageChange(page: number): void { this.usuarioState.setCurrentPage(page); this.loadUsuarios(); }

  abrirModalCrear(): void { this.isEditing = false; this.currentUsuario = null; this.modalTitle = 'Crear Nuevo Usuario'; this.showUsuarioModal = true; }
  abrirModalEditar(usuario: Usuario): void { this.isEditing = true; this.currentUsuario = usuario; this.modalTitle = 'Editar Usuario'; this.showUsuarioModal = true; }
  abrirModalCambiarPassword(usuario: Usuario): void {
     this.currentUsuario = usuario;
     this.passwordData = { currentPassword: '', newPassword: '', confirmPassword: '', contrasena: ''};
     this.passwordError = '';
      this.showPasswordModal = true; }
  abrirModalEliminar(usuario: Usuario): void { this.currentUsuario = usuario; this.showDeleteModal = true; }
  abrirModalRoles(): void { this.showRolesModal = true; }
  abrirModalReportes(): void { this.showReportesModal = true; }
  cerrarModales(): void { this.showUsuarioModal = false; this.showPasswordModal = false; this.showDeleteModal = false; this.showRolesModal = false; this.showReportesModal = false; this.showValidacionModal = false; this.currentUsuario = null; }

  guardarUsuario(usuarioData: any): void {
    if (this.isEditing && this.currentUsuario) {
      this.usuarioService.actualizar(this.currentUsuario.usuario_id, usuarioData).subscribe({
        next: () => {
          this.usuarioState.updateUsuario(this.currentUsuario!.usuario_id, usuarioData);
          this.showUsuarioModal = false;
          this.currentUsuario = null;
          this.notificationService?.showSuccess('Usuario actualizado exitosamente');
        },
        error: (error) => {
          console.error('Error updating usuario:', error);
          this.notificationService?.showError('Error al actualizar usuario');
        }
      });
    } else {
      this.usuarioService.crear(usuarioData).subscribe({
        next: (response) => {
          this.usuarioState.addUsuario(response.data);
          this.showUsuarioModal = false;
          this.notificationService?.showSuccess('Usuario creado exitosamente');
        },
        error: (error) => {
          console.error('Error creating usuario:', error);
          this.notificationService?.showError('Error al crear usuario');
        }
      });
    }
  }

 cambiarPassword(): void {
  // ✅ Validar que la contraseña actual esté presente
  if (!this.passwordData.currentPassword || this.passwordData.currentPassword.trim() === '') {
    this.passwordError = 'La contraseña actual es requerida';
    this.notificationService?.showError(this.passwordError);
    return;
  }

  // Validar fortaleza de la nueva contraseña
  const passwordStrength = usuarioValidators.passwordStrengthStrict({ value: this.passwordData.newPassword } as any);
  const passwordMatch = this.passwordData.newPassword === this.passwordData.confirmPassword;

  if (passwordStrength !== null) {
    this.passwordError = 'La contraseña debe tener: mínimo 8 caracteres, una mayúscula, una minúscula, un número y un carácter especial';
    this.notificationService?.showError(this.passwordError);
    return;
  }

  if (!passwordMatch) {
    this.passwordError = 'Las contraseñas no coinciden';
    this.notificationService?.showError(this.passwordError);
    return;
  }

  if (this.currentUsuario) {
    // ✅ Siempre enviar current_password
    const payload = {
      current_password: this.passwordData.currentPassword,  // ← Siempre presente
      password: this.passwordData.newPassword,
      password_confirmation: this.passwordData.confirmPassword
    };

    console.log('📤 Cambiando contraseña para usuario:', this.currentUsuario.usuario_id);

    this.usuarioService.cambiarPassword(this.currentUsuario.usuario_id, payload).subscribe({
      next: () => {
        this.showPasswordModal = false;
        this.currentUsuario = null;
        // Limpiar el formulario
        this.passwordData = {
          currentPassword: '',
          newPassword: '',
          confirmPassword: '',
          contrasena: ''
        };
        this.passwordError = '';
        this.notificationService?.showSuccess('Contraseña cambiada exitosamente');
      },
      error: (error) => {
        console.error('❌ Error al cambiar contraseña:', error);
        const mensaje = error.error?.message || error.message || 'Error al cambiar contraseña';
        this.notificationService?.showError(mensaje);
      }
    });
  }
}

  eliminarUsuario(): void {
    if (this.currentUsuario) {
      this.usuarioService.eliminar(this.currentUsuario.usuario_id).subscribe({
        next: () => {
          this.usuarioState.removeUsuario(this.currentUsuario!.usuario_id);
          this.showDeleteModal = false;
          this.currentUsuario = null;
          this.notificationService?.showSuccess('Usuario eliminado exitosamente');
        },
        error: (error) => {
          console.error('Error deleting usuario:', error);
          this.notificationService?.showError('Error al eliminar usuario');
        }
      });
    }
  }

onFiltersChange(filters: any): void {
  // ✅ Limpiar filtros con null
  const cleanFilters: any = {};

  if (filters.search && filters.search.trim() !== '') {
    cleanFilters.search = filters.search;
  }
  if (filters.rol_id !== null && filters.rol_id !== undefined && filters.rol_id !== '') {
    cleanFilters.rol_id = filters.rol_id;
  }
  if (filters.activo !== null && filters.activo !== undefined && filters.activo !== '') {
    cleanFilters.activo = filters.activo;
  }

  this.usuarioState.setFilters(cleanFilters);
  this.filterSubject.next(cleanFilters);
}

toggleUsuarioActivo(usuario: Usuario): void {
  const nuevoEstado = !usuario.activo;
  const accion = nuevoEstado ? 'activar' : 'desactivar';

  if (confirm(`¿Está seguro de ${accion} este usuario?`)) {
    // ✅ Enviar booleano explícito (true/false, no 1/0)
    const data = { activo: nuevoEstado === true };

    console.log('📤 Desactivando usuario:', { usuario_id: usuario.usuario_id, activo: data.activo });

    this.usuarioService.actualizar(usuario.usuario_id, data).subscribe({
      next: () => {
        this.usuarioState.updateUsuario(usuario.usuario_id, { activo: nuevoEstado });
        this.notificationService?.showSuccess(`Usuario ${accion}do exitosamente`);
      },
      error: (error) => {
        console.error(`Error al ${accion} usuario:`, error);
        this.notificationService?.showError(`Error al ${accion} usuario`);
      }
    });
  }
}

  // ========== MÉTODOS AUXILIARES ==========
get usuariosConectados(): number {
  // Obtener usuarios actuales del estado
  let usuariosActuales: Usuario[] = [];
  this.usuarioState.state$.subscribe(state => {
    usuariosActuales = state.usuarios;
  }).unsubscribe();

  const cincoMinutosAtras = new Date(Date.now() - 5 * 60 * 1000);
  return usuariosActuales.filter(u => {
    if (!u.ultimo_acceso) return false;
    const ultimoAcceso = new Date(u.ultimo_acceso);
    return ultimoAcceso > cincoMinutosAtras;
  }).length;
}
  get rolesActivos(): number { return 6; }
  get esAutenticacionPropia(): boolean { return this.currentUsuario?.nombre_usuario === this.user.name; }

  validarNuevaContrasena(): void {
    const pwd = this.passwordData.newPassword;
    if (!pwd) {
      this.passwordReqs = { minLength: false, hasUppercase: false, hasLowercase: false, hasNumber: false, hasSpecial: false, valid: false };
      return;
    }

    const isValid = usuarioValidators.passwordStrength({ value: pwd } as any) === null;

    this.passwordReqs = {
      minLength: pwd.length >= 8,
      hasUppercase: /[A-Z]/.test(pwd),
      hasLowercase: /[a-z]/.test(pwd),
      hasNumber: /[0-9]/.test(pwd),
      hasSpecial: /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(pwd),
      valid: isValid
    };
  }

  validarConfirmacionContrasena(): void {
    this.passwordError = (this.passwordData.newPassword !== this.passwordData.confirmPassword) ? 'Las contraseñas no coinciden' : '';
  }

  getPasswordStrengthClass(): string {
    const met = Object.values(this.passwordReqs).filter(Boolean).length;
    if (met === 5) return 'strength-very-strong';
    if (met >= 4) return 'strength-strong';
    if (met >= 3) return 'strength-medium';
    return 'strength-weak';
  }

  getPasswordStrengthText(): string {
    const clase = this.getPasswordStrengthClass();
    if (clase === 'strength-very-strong') return 'Muy fuerte';
    if (clase === 'strength-strong') return 'Fuerte';
    if (clase === 'strength-medium') return 'Medio';
    return 'Débil';
  }

  generarReportes(): void { this.showReportesModal = true; }
  generarReporteActividadGeneral(): void { console.log('Generando reporte'); }
  generarReportePorRol(): void { console.log('Generando reporte por rol'); }
  generarReporteInactivos(): void { console.log('Generando reporte inactivos'); }
  generarReporteSeguridad(): void { console.log('Generando reporte seguridad'); }
  generarReporteActividad(): void { this.generarReporteActividadGeneral(); }
  exportarReportePDF(): void { console.log('Exportando PDF'); }
  exportarReporteExcel(): void { console.log('Exportando Excel'); }
  programarReporte(): void { alert('Reporte programado para envío periódico'); }
  validarCredenciales(): void { this.showValidacionModal = true; }



}
