import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { map, distinctUntilChanged } from 'rxjs/operators';

export interface Usuario {
  usuario_id: number;
  nombre_usuario: string;
  email: string;
  personal_id: number;
  rol_id: number;
  activo: boolean;
  requiere_cambio_contrasena: boolean;
  fecha_creacion?: string;
  ultimo_acceso?: string;
  intentos_fallidos?: number;
  fecha_bloqueo?: string;
  rol_nombre?: string;
  estado?: string;
  persona_nombres?: string;
  persona_apellidos?: string;
  persona_documento?: string;
  personal?: {
    persona_id: number;
    nombres: string;
    apellidos: string;
    numero_documento: string;
  };
  rol?: {
    rol_id: number;
    nombre: string;
    descripcion: string;
  };
}

export interface UsuarioState {
  usuarios: Usuario[];
  loading: boolean;
  error: string | null;
  totalItems: number;
  currentPage: number;
  perPage: number;
  filters: any;
}

const initialState: UsuarioState = {
  usuarios: [],
  loading: false,
  error: null,
  totalItems: 0,
  currentPage: 1,
  perPage: 10,
  filters: {}
};

@Injectable({ providedIn: 'root' })
export class UsuarioStateService {
  private state = new BehaviorSubject<UsuarioState>(initialState);
  public state$ = this.state.asObservable();

  selectUsuarios(): Observable<Usuario[]> {
    return this.state$.pipe(map(state => state.usuarios), distinctUntilChanged());
  }

  selectLoading(): Observable<boolean> {
    return this.state$.pipe(map(state => state.loading), distinctUntilChanged());
  }

  selectError(): Observable<string | null> {
    return this.state$.pipe(map(state => state.error), distinctUntilChanged());
  }

  selectTotalItems(): Observable<number> {
    return this.state$.pipe(map(state => state.totalItems), distinctUntilChanged());
  }

  selectCurrentPage(): Observable<number> {
    return this.state$.pipe(map(state => state.currentPage), distinctUntilChanged());
  }

  selectFilters(): Observable<any> {
    return this.state$.pipe(map(state => state.filters), distinctUntilChanged());
  }

  setLoading(loading: boolean): void {
    this.state.next({ ...this.state.value, loading });
  }

  setUsuarios(usuarios: Usuario[], totalItems: number): void {
    this.state.next({
      ...this.state.value,
      usuarios,
      totalItems,
      loading: false,
      error: null
    });
  }

  setError(error: string): void {
    this.state.next({ ...this.state.value, error, loading: false });
  }

  setCurrentPage(page: number): void {
    this.state.next({ ...this.state.value, currentPage: page });
  }

  setFilters(filters: any): void {
  const cleanFilters: any = {};
  if (filters.search) cleanFilters.search = filters.search;
  if (filters.rol_id !== null && filters.rol_id !== undefined) cleanFilters.rol_id = filters.rol_id;
  if (filters.activo !== null && filters.activo !== undefined) cleanFilters.activo = filters.activo;

  this.state.next({ ...this.state.value, filters: cleanFilters, currentPage: 1 });
}


  addUsuario(usuario: Usuario): void {
    this.state.next({
      ...this.state.value,
      usuarios: [usuario, ...this.state.value.usuarios],
      totalItems: this.state.value.totalItems + 1
    });
  }

  updateUsuario(usuarioId: number, changes: Partial<Usuario>): void {
    const usuarios = this.state.value.usuarios.map(u =>
      u.usuario_id === usuarioId ? { ...u, ...changes } : u
    );
    this.state.next({ ...this.state.value, usuarios });
  }

  removeUsuario(usuarioId: number): void {
    const usuarios = this.state.value.usuarios.filter(u => u.usuario_id !== usuarioId);
    this.state.next({
      ...this.state.value,
      usuarios,
      totalItems: this.state.value.totalItems - 1
    });
  }

  resetState(): void {
    this.state.next(initialState);
  }
}
